using System.Net;
using System.Net.Http.Json;
using System.Security.Cryptography;
using System.Text.Json;
using UnscRelay.Core;
internal static class ErasureTrackingChecks
{
 sealed class Server(string directory):HttpMessageHandler
 {
  public readonly ECDsa Key=ECDsa.Create(ECCurve.NamedCurves.nistP256);public Guid Request=Guid.NewGuid();public string State="pending";public DateTimeOffset Deadline=DateTimeOffset.UtcNow.AddDays(-1);public string? Hash;public Guid LastLookupRequest;public int Registrations,Lookups;public bool Persisted,WrongRequest,WrongOwner,Offline,StatusOffline,ChangedEnrollment;
  public string KeyId=>Convert.ToHexString(SHA256.HashData(Key.ExportSubjectPublicKeyInfo()))[..32];
  protected override async Task<HttpResponseMessage> SendAsync(HttpRequestMessage request,CancellationToken ct){if(request.RequestUri!.Scheme!="https"||request.RequestUri.Host!="unsc.responda.eu")throw new Exception("Untrusted origin");if(request.RequestUri.AbsolutePath=="/account-erasure/receipt"){Lookups++;if(request.Headers.Authorization!=null||request.Headers.Contains("Cookie"))throw new Exception("Recovery request leaked session credentials");if(Offline)throw new HttpRequestException("Synthetic outage");var body=await request.Content!.ReadFromJsonAsync<JsonElement>(ct);LastLookupRequest=body.GetProperty("requestId").GetGuid();var capability=body.GetProperty("capability").GetString()!;var secret=Convert.FromBase64String(capability.Replace('-','+').Replace('_','/')+"=");try{if(Hash!=Convert.ToHexString(SHA256.HashData(secret)))return new(HttpStatusCode.NoContent);}finally{CryptographicOperations.ZeroMemory(secret);}if(State is "pending" or "cancelled")return new(HttpStatusCode.NoContent);var claims=new ErasureReceiptClaims(1,"https://unsc.responda.eu","unsc-relay-desktop-erasure",new string(WrongOwner?'B':'A',64),"51515151-5151-4151-8151-515151515151",WrongRequest?Guid.NewGuid():Request,Deadline.AddDays(-30).ToUnixTimeMilliseconds(),Deadline.ToUnixTimeMilliseconds(),"completed",DateTimeOffset.UtcNow.ToUnixTimeMilliseconds());var bytes=JsonSerializer.SerializeToUtf8Bytes(claims,VaultSyncCrypto.Json);string Enc(byte[] value)=>Convert.ToBase64String(value).TrimEnd('=').Replace('+','-').Replace('/','_');return new(HttpStatusCode.OK){Content=JsonContent.Create(new{receipt=new ErasureReceipt(KeyId,Enc(bytes),Enc(Key.SignData(bytes,HashAlgorithmName.SHA256,DSASignatureFormat.IeeeP1363FixedFieldConcatenation)))},options:VaultSyncCrypto.Json)};}
   if(StatusOffline)throw new HttpRequestException("Synthetic authenticated status outage");if(request.Headers.Authorization?.Parameter!="synthetic-access")throw new Exception("Missing authenticated tracking identity");if(request.RequestUri.AbsolutePath.EndsWith("/receipt-capability",StringComparison.Ordinal)){Registrations++;var enrollment=await request.Content!.ReadFromJsonAsync<JsonElement>(ct);if(enrollment.GetProperty("requestId").GetGuid()!=Request)throw new Exception("Enrollment lost deletion request binding");if(ChangedEnrollment)return new(HttpStatusCode.Conflict){Content=JsonContent.Create(new{error="Synthetic changed request"})};Hash=enrollment.GetProperty("hash").GetString();var saved=new AccountSyncStore(directory).Load();Persisted=saved.ErasureRequestId==Request&&saved.ErasureCapability.Length==43&&!saved.ErasureCapabilityRegistered;return new(HttpStatusCode.OK){Content=JsonContent.Create(new{})};}return new(HttpStatusCode.OK){Content=JsonContent.Create(new{status=new{state=State,requestId=Request,requestedAt=Deadline.AddDays(-30),executeAfter=Deadline,graceDays=30}})};
  }
 }
 public static async Task<int> Run(){var root=Directory.CreateTempSubdirectory("relay-erasure-tracking-");var count=0;void Check(bool value,string label){if(!value)throw new Exception(label);count++;Console.WriteLine("PASS erasure tracking: "+label);}try{var server=new Server(root.FullName);using var client=new CloudAccountClient(root.FullName,server);client.State.Activated=true;client.State.Owner=new string('A',64);client.State.Subject="51515151-5151-4151-8151-515151515151";client.State.AccessToken="synthetic-access";client.State.TokenExpires=DateTimeOffset.UtcNow.AddHours(1);server.ChangedEnrollment=true;try{await client.RefreshErasureTracking(CancellationToken.None);throw new Exception("Changed enrollment accepted");}catch(OnlineAccessException error)when(error.Status==HttpStatusCode.Conflict){Check(!client.State.ErasureCapabilityRegistered&&client.State.ErasureRequestId==server.Request,"changed request during enrollment leaves the exact original device proof retryable");}server.ChangedEnrollment=false;var verifier=new ErasureReceiptVerifier(new Dictionary<string,string>{{server.KeyId,Convert.ToBase64String(server.Key.ExportSubjectPublicKeyInfo())}});await client.RefreshErasureTracking(CancellationToken.None);Check(server.Persisted&&client.State.ErasureCapabilityRegistered,"device capability is durably protected before its hash is enrolled");Check(!System.Text.Encoding.UTF8.GetString(File.ReadAllBytes(Path.Combine(root.FullName,"account-sync.dpapi"))).Contains(client.State.ErasureCapability,StringComparison.Ordinal),"plaintext recovery capability is absent from account metadata on disk");await client.RefreshErasureTracking(CancellationToken.None);Check(server.Registrations==2,"ordinary status refresh reuses the enrolled device proof");try{await client.CheckErasureAccess(CancellationToken.None);throw new Exception("Expired pending account opened after 204");}catch(ErasureVerificationPendingException){Check(true,"expired deadline plus 204 keeps access blocked without deleting files");}server.Offline=server.StatusOffline=true;try{await client.CheckErasureAccess(CancellationToken.None);throw new Exception("Expired offline account opened");}catch(ErasureVerificationPendingException){Check(true,"expired deadline plus unavailable receipt and authenticated status keeps access blocked");}server.Offline=server.StatusOffline=false;await client.LogoutAsync(CancellationToken.None);Check(client.State.Owner==new string('A',64)&&client.State.Subject=="51515151-5151-4151-8151-515151515151"&&client.State.ErasureCapability.Length==43,"logout retains deletion tracking even for an archive that has never been migrated");client.State.Activated=false;client.State.TokenExpires=DateTimeOffset.MinValue;client.State.AccessToken="";Check(await client.PollErasureReceipt(CancellationToken.None,verifier)==null,"pending account produces no destruction receipt even without a sign-in session");server.State="completed";var proof=await client.PollErasureReceipt(CancellationToken.None,verifier);Check(proof?.Claims.RequestId==server.Request,"receipt remains verifiable after token expiration and explicit disconnection");foreach(var kind in new[]{"request","owner"}){server.WrongRequest=kind=="request";server.WrongOwner=kind=="owner";try{await client.PollErasureReceipt(CancellationToken.None,verifier);throw new Exception("Wrong receipt accepted");}catch(InvalidDataException){Check(true,"signed receipt for another "+kind+" never authorizes local cleanup");}}server.WrongOwner=server.WrongRequest=false;server.Offline=true;var before=client.State.ErasureCapability;try{await client.PollErasureReceipt(CancellationToken.None,verifier);throw new Exception("Outage accepted");}catch(HttpRequestException){Check(client.State.ErasureCapability==before,"network failure preserves the pending proof without pretending deletion completed");}server.Offline=false;server.State="cancelled";client.State.Activated=true;client.State.AccessToken="synthetic-access";client.State.TokenExpires=DateTimeOffset.UtcNow.AddHours(1);Check(await client.CheckErasureAccess(CancellationToken.None)==null,"authenticated cancellation releases the deadline gate after a public 204");Check(client.State.ErasureRequestId==Guid.Empty&&client.State.ErasureCapability==""&&client.State.ErasureExecuteAfter==null,"authenticated cancellation retires only this device's obsolete receipt proof");server.State="pending";await client.RefreshErasureTracking(CancellationToken.None);var previous=server.Request;var oldCapability=client.State.ErasureCapability;server.Request=Guid.NewGuid();server.Deadline=DateTimeOffset.UtcNow.AddDays(20);await client.RefreshErasureTracking(CancellationToken.None);Check(server.LastLookupRequest==previous,"unobserved cancellation and rescheduling probes the old permanent receipt before replacing its binding");Check(client.State.ErasureRequestId==server.Request&&client.State.ErasureCapability!=oldCapability&&client.State.ErasureCapabilityRegistered,"authenticated future request gets a separate durable capability");var lookups=server.Lookups;Check(await client.CheckErasureAccess(CancellationToken.None)==null&&server.Lookups==lookups,"future deletion deadline does not poll an impossible permanent receipt");server.Key.Dispose();Console.WriteLine("Erasure tracking checks: "+count);return 0;}finally{root.Delete(true);}}
}
